/**
 * =============================================================================
 * E2E STORE HOOKS
 * =============================================================================
 *
 * High-level hooks for e2e testing that expose meaningful store queries.
 * These provide convenient access to commonly tested store state.
 *
 * @module tests/e2e/helper/hooks
 */

import { Page } from "@playwright/test";
import {
  getAlgoTradeRows,
  getBacktestParams,
  getEntryInfo,
  getAlgoTotalPnL,
  getRoundTripCount,
  getLatestEntryPrice,
  getLatestExitReason,
  validateAlgoTradePairs,
  getStrategyResultsSummary,
} from './store-queries';

/**
 * Hook for accessing current algo trade data.
 * Returns commonly needed trade information for validation.
 */
export async function useAlgoTrades(page: Page) {
  const [trades, totalPnL, roundTrips] = await Promise.all([
    getAlgoTradeRows(page),
    getAlgoTotalPnL(page),
    getRoundTripCount(page),
  ]);

  return {
    trades,
    totalPnL,
    roundTrips,
    hasTrades: trades.length > 0,
    latestEntry: await getLatestEntryPrice(page),
    latestExitReason: await getLatestExitReason(page),
    isValid: (await validateAlgoTradePairs(page)).valid,
  };
}

/**
 * Hook for accessing current backtest configuration.
 * Returns all relevant parameters for preset and strategy validation.
 */
export async function useBacktestConfig(page: Page) {
  const params = await getBacktestParams(page);

  return {
    ...params,
    hasValidParams: Boolean(
      params.profitTargetPts &&
      params.stopLossPts &&
      params.triggerPts &&
      params.strategy
    ),
  };
}

/**
 * Hook for accessing entry and direction information.
 * Returns algo-derived entry data for validation.
 */
export async function useEntryInfo(page: Page) {
  const entryInfo = await getEntryInfo(page);

  return {
    ...entryInfo,
    hasEntry: entryInfo.entryPrice !== null && entryInfo.entryPrice !== undefined,
    isLong: entryInfo.direction === 'long',
    isShort: entryInfo.direction === 'short',
  };
}

/**
 * Hook for accessing multi-day strategy performance.
 * Returns aggregated results across multiple trading days.
 */
export async function useStrategyPerformance(page: Page) {
  const summary = await getStrategyResultsSummary(page);

  return {
    ...summary,
    isProfitable: summary.totalPnL > 0,
    hasMultipleDays: summary.days > 1,
  };
}

/**
 * Hook for validating complete backtest state.
 * Performs comprehensive checks on all critical state components.
 */
export async function useBacktestValidation(page: Page) {
  const [config, entry, trades, performance] = await Promise.all([
    useBacktestConfig(page),
    useEntryInfo(page),
    useAlgoTrades(page),
    useStrategyPerformance(page),
  ]);

  return {
    config,
    entry,
    trades,
    performance,
    isReady: config.hasValidParams && entry.hasEntry,
    hasCompleteWorkflow: config.hasValidParams && entry.hasEntry && trades.hasTrades,
  };
}

