/**
 * =============================================================================
 * TEST E2E HELPERS - REAL FUNCTIONALITY
 * =============================================================================
 *
 * Test script to verify that helper functions work in real browser scenarios.
 * Tests actual functionality with browser state.
 */

import { expect, test } from "@playwright/test";
const helpers = require('./helper');

test.describe('E2E Helper Real Functionality', () => {
  test.beforeEach(async ({ page }) => {
    page.on("console", (msg) => {
      // Surface browser logs for debugging
      console.log(`[browser:${msg.type()}]`, msg.text());
