    const hookFunctions = ['useAlgoTrades', 'useBacktestConfig', 'useEntryInfo'];

    // All expected functions should exist
    [...waitFunctions, ...authFunctions, ...uiFunctions, ...storeFunctions, ...hookFunctions]
      .forEach(fnName => {
        expect(typeof helpers[fnName]).toBe('function');
      });

    console.log('✅ Migration enables better test organization');
  });

  test('can import individual helper functions', async () => {
    // Test that individual imports work (like the migration guide shows)
    const { waitForAlgoTrades, getAlgoTotalPnL } = require('./helper');

    expect(typeof waitForAlgoTrades).toBe('function');
    expect(typeof getAlgoTotalPnL).toBe('function');

    console.log('✅ Can import individual helper functions');
  });
});

