/**
 * Unit tests for e2e helper logic (without playwright dependencies)
 * Tests the core algorithms and calculations used by helpers
 */

describe('Helper Function Logic', () => {
  test('calculateAlgoTotalPnL sums close row nets correctly', () => {
    // Simulate the logic from getAlgoTotalPnL
    const trades = [
      { id: 'open-1', type: 'Open Long', price: 100 },
      { id: 'close-1', type: 'Close Long', price: 105, net: 5 },
      { id: 'open-2', type: 'Open Short', price: 105 },
      { id: 'close-2', type: 'Close Short', price: 102, net: 3 },
      { id: 'open-3', type: 'Open Long', price: 102 },
      { id: 'close-3', type: 'Close Long', price: 102, net: 0 } // EOD push
    ];

    let total = 0;
    for (const trade of trades) {
      if (trade.type.includes('Close') && trade.net !== undefined) {
        total += trade.net;
      }
    }

    expect(total).toBe(8); // 5 + 3 + 0 = 8
  });

  test('validateAlgoTradePairs detects valid open/close pairs', () => {
    // Valid pairs: alternating Open/Close
    const validTrades = [
      { id: 'open-1', type: 'Open Long', timestamp: '2025-01-01T09:30:00Z' },
      { id: 'close-1', type: 'Close Long', timestamp: '2025-01-01T10:30:00Z' },
      { id: 'open-2', type: 'Open Short', timestamp: '2025-01-01T11:00:00Z' },
      { id: 'close-2', type: 'Close Short', timestamp: '2025-01-01T12:00:00Z' }
    ];

    // Check pair count
    expect(validTrades.length % 2).toBe(0);

    // Check alternating pattern
    for (let i = 0; i < validTrades.length; i++) {
      const expectedType = i % 2 === 0 ? 'Open' : 'Close';
      expect(validTrades[i].type.includes(expectedType)).toBe(true);
    }

    // Check monotonic timestamps
    for (let i = 1; i < validTrades.length; i++) {
      const prevTime = new Date(validTrades[i - 1].timestamp).getTime();
      const currTime = new Date(validTrades[i].timestamp).getTime();
      expect(currTime).toBeGreaterThanOrEqual(prevTime);
    }
  });

  test('validateAlgoTradePairs detects invalid pairs', () => {
    // Invalid: Close before Open
    const invalidTrades = [
      { id: 'close-1', type: 'Close Long', timestamp: '2025-01-01T10:30:00Z' },
      { id: 'open-1', type: 'Open Long', timestamp: '2025-01-01T09:30:00Z' }
    ];

    // Should detect wrong order
    const firstTrade = invalidTrades[0];
    const expectedType = 'Open'; // i=0 should be Open
    expect(firstTrade.type.includes(expectedType)).toBe(false);

    // Should detect non-monotonic timestamps
    const prevTime = new Date(invalidTrades[0].timestamp).getTime();
    const currTime = new Date(invalidTrades[1].timestamp).getTime();
    expect(currTime).toBeLessThan(prevTime);
  });

  test('getRoundTripCount counts close rows correctly', () => {
    const trades = [
      { id: 'open-1', type: 'Open Long' },
      { id: 'close-1', type: 'Close Long', net: 5 },
      { id: 'open-2', type: 'Open Short' },
      { id: 'close-2', type: 'Close Short', net: -2 },
      { id: 'open-3', type: 'Open Long' },
      { id: 'close-3', type: 'Close Long', net: 0 }
    ];

    const roundTrips = trades.filter(trade => trade.type.includes('Close')).length;
    expect(roundTrips).toBe(3);
  });

  test('getLatestEntryPrice finds most recent open trade', () => {
    const trades = [
      { id: 'open-1', type: 'Open Long', price: 100 },
      { id: 'close-1', type: 'Close Long', price: 105, net: 5 },
      { id: 'open-2', type: 'Open Short', price: 102 },
      { id: 'close-2', type: 'Close Short', price: 99, net: -3 },
      { id: 'open-3', type: 'Open Long', price: 101 } // Most recent
    ];

    const openRows = trades.filter(trade => trade.type.includes('Open'));
    const latestOpen = openRows[openRows.length - 1];

    expect(latestOpen.price).toBe(101);
  });

  test('getLatestExitReason finds most recent close trade note', () => {
    const trades = [
      { id: 'open-1', type: 'Open Long', price: 100 },
      { id: 'close-1', type: 'Close Long', price: 105, net: 5, note: 'PT Hit' },
      { id: 'open-2', type: 'Open Short', price: 105 },
      { id: 'close-2', type: 'Close Short', price: 102, net: 3, note: 'SL Hit' } // Most recent
    ];

    const closeRows = trades.filter(trade => trade.type.includes('Close'));
    const latestClose = closeRows[closeRows.length - 1];

    expect(latestClose.note).toBe('SL Hit');
  });

  test('getStrategyResultsSummary calculates averages correctly', () => {
    const results = {
      '2025-01-01': { pnl: 5 },
      '2025-01-02': { pnl: -2 },
      '2025-01-03': { pnl: 8 }
    };

    const days = Object.keys(results).length;
    const totalPnL = Object.values(results).reduce((sum, day) => sum + day.pnl, 0);
    const avgPnL = days > 0 ? totalPnL / days : 0;

    expect(days).toBe(3);
    expect(totalPnL).toBe(11); // 5 + (-2) + 8 = 11
    expect(avgPnL).toBeCloseTo(3.666, 1); // 11/3 ≈ 3.667
  });

  test('getStrategyResultsSummary handles empty results', () => {
    const results = null;

    if (!results) {
      const summary = { days: 0, totalPnL: 0, avgPnL: 0 };
      expect(summary.days).toBe(0);
      expect(summary.totalPnL).toBe(0);
      expect(summary.avgPnL).toBe(0);
    }
  });

  test('useBacktestConfig validation logic works', () => {
    // Valid config
    const validParams = {
      profitTargetPts: 36,
      stopLossPts: 7,
      triggerPts: 6,
      strategy: 'test-strategy'
    };

    const hasValidParams = Boolean(
      validParams.profitTargetPts &&
      validParams.stopLossPts &&
      validParams.triggerPts &&
      validParams.strategy
    );

    expect(hasValidParams).toBe(true);

    // Invalid config (missing strategy)
    const invalidParams = {
      profitTargetPts: 36,
      stopLossPts: 7,
      triggerPts: 6,
      strategy: null
    };

    const hasInvalidParams = Boolean(
      invalidParams.profitTargetPts &&
      invalidParams.stopLossPts &&
      invalidParams.triggerPts &&
      invalidParams.strategy
    );

    expect(hasInvalidParams).toBe(false);
  });

  test('useEntryInfo validation flags work correctly', () => {
    // Valid entry
    const validEntry = { entryPrice: 101.5, direction: 'long' };
    const hasEntry = validEntry.entryPrice !== null && validEntry.entryPrice !== undefined;
    const isLong = validEntry.direction === 'long';
    const isShort = validEntry.direction === 'short';

    expect(hasEntry).toBe(true);
    expect(isLong).toBe(true);
    expect(isShort).toBe(false);

    // Invalid entry
    const invalidEntry = { entryPrice: null, direction: 'long' };
    const hasNoEntry = invalidEntry.entryPrice !== null && invalidEntry.entryPrice !== undefined;

    expect(hasNoEntry).toBe(false);
  });

  test('useStrategyPerformance calculates profitability correctly', () => {
    const summary = { days: 3, totalPnL: 11, avgPnL: 3.67 };

    const isProfitable = summary.totalPnL > 0;
    const hasMultipleDays = summary.days > 1;

    expect(isProfitable).toBe(true);
    expect(hasMultipleDays).toBe(true);

    // Test unprofitable case
    const lossSummary = { days: 2, totalPnL: -5, avgPnL: -2.5 };
    const isUnprofitable = lossSummary.totalPnL > 0;

    expect(isUnprofitable).toBe(false);
  });
});

